class Solution:
    def maxEqual(self, a: List[int]) -> int:
        n = len(a); v = sorted(set(a)); best = 0; j = 0
        for i in range(len(v)):
            while v[i] - v[j] > n - 1: j += 1
            best = max(best, i - j + 1)
        return best

